import { model, Schema } from "mongoose";
import {
  FeedIngredientCategories,
  FeedIngredientUnits,
} from "./feedIngredient.constants.js";
import type { TFeedIngredient } from "./feedIngredient.interface.js";

const percent = { type: Number, min: 0, max: 100 };

const feedIngredientSchema = new Schema<TFeedIngredient>(
  {
    //generated by generateIngredientCode (ING-00001) and never accepted from the client
    ingredientCode: {
      type: String,
      required: true,
      unique: true,
      immutable: true,
      trim: true,
      uppercase: true,
    },
    ingredientName: { type: String, required: true, trim: true, maxlength: 100 },
    unit: { type: String, enum: Object.values(FeedIngredientUnits), required: true },
    category: {
      type: String,
      enum: Object.values(FeedIngredientCategories),
      required: true,
    },
    //nutrition reference values: never negative, percentages capped at 100
    dryMatterPercentage: { ...percent, required: true },
    crudeProtein: { ...percent, required: true },
    crudeFiber: { ...percent, required: true },
    energy: { type: Number, min: 0, required: true }, //Mcal/kg
    calcium: percent,
    phosphorus: percent,
    pricePerUnit: { type: Number, min: 0, required: true },
    availability: { type: Number, min: 0 },
    supplierId: { type: Schema.Types.ObjectId, ref: "Supplier" },
    description: { type: String, trim: true, maxlength: 2000 },
    isAvailable: { type: Boolean, required: true, default: true },
    //retired instead of deleted so formulas/recommendations/records keep valid references
    isActive: { type: Boolean, required: true, default: true },
  },
  { timestamps: true },
);

//one canonical record per name, case-insensitively ("Rice Bran" vs "rice bran")
feedIngredientSchema.index(
  { ingredientName: 1 },
  { unique: true, collation: { locale: "en", strength: 2 } },
);

//formula-builder / selection screens: active + available ingredients by category
feedIngredientSchema.index({ category: 1, isActive: 1, isAvailable: 1 });
feedIngredientSchema.index({ supplierId: 1 });

export const FeedIngredientModel = model<TFeedIngredient>(
  "FeedIngredient",
  feedIngredientSchema,
);
